class Solution {
public:
    int numEquivDominoPairs(vector<vector<int>>& dominoes) {
        map<int, int> cnt;
        int pairs = 0;
        for (int i = 0; i < (int)dominoes.size(); i++) {
            int a = dominoes[i][0], b = dominoes[i][1];
            int key = min(a, b) * 10 + max(a, b);
            pairs += cnt[key]++;
        }
        return pairs;
    }
};
